+          <p class="eyebrow">Support team</p>
+          <h1 id="support-title">Get in touch with product support</h1>
+          <p>
+            Send us your details and our team will follow up with the right next step,
+            troubleshooting guidance, or account help.
+          </p>
+        </div>
+
+        <div class="contact-card">
+          <h2>Contact support</h2>
+          <p>Fill out the form below and we will reply as soon as possible.</p>
+          <p class="required-note"><span aria-hidden="true">*</span> Required fields</p>
+
+          <form id="support-form" novalidate>
+            <div class="form-field">
+              <label for="full-name">
+                Full name
+                <span class="required-indicator" aria-hidden="true">*</span>
+                <span class="visually-hidden"> required</span>
+              </label>
+              <input
+                id="full-name"
+                name="fullName"
+                type="text"
+                autocomplete="name"
+                required
+                aria-describedby="full-name-error"
+                aria-errormessage="full-name-error"
+                placeholder="Jordan Lee"
+              >
+              <p id="full-name-error" class="error-text" hidden></p>
+            </div>
+
+            <div class="form-field">
