  <a class="skip-link" href="#main-content">Skip to main content</a>
  <main id="main-content" class="page-shell" tabindex="-1">
    <section class="hero" aria-labelledby="support-title">
      <div class="hero-grid">
        <div class="hero-copy">
          <p class="eyebrow">Support team</p>
          <h1 id="support-title">Get in touch with product support</h1>
          <p>
            Send us your details and our team will follow up with the right next step,
            troubleshooting guidance, or account help.
          </p>
        </div>

        <div class="contact-card">
          <h2>Contact support</h2>
          <p>Fill out the form below and we will reply as soon as possible.</p>
          <p class="required-note"><span aria-hidden="true">*</span> Required fields</p>

          <form id="support-form" novalidate>
            <div class="form-field">
              <label for="full-name">
                Full name
                <span class="required-indicator" aria-hidden="true">*</span>
                <span class="visually-hidden"> required</span>
              </label>
              <input
                id="full-name"
                name="fullName"
                type="text"
                autocomplete="name"
                required
                aria-describedby="full-name-error"
                aria-errormessage="full-name-error"
                placeholder="Jordan Lee"
              >
              <p id="full-name-error" class="error-text" hidden></p>
            </div>

            <div class="form-field">
              <label for="email-address">
                Email address
                <span class="required-indicator" aria-hidden="true">*</span>
                <span class="visually-hidden"> required</span>
              </label>
              <input
                id="email-address"
                name="email"
                type="email"
                inputmode="email"
                autocomplete="email"
                required
                aria-describedby="email-address-error"
                aria-errormessage="email-address-error"
                placeholder="jordan@example.com"
              >
              <p id="email-address-error" class="error-text" hidden></p>
            </div>

            <div class="form-field">
              <label for="phone-number">Phone number <span class="helper-inline">(optional)</span></label>
              <input
                id="phone-number"
                name="phone"
                type="tel"
                inputmode="tel"
                autocomplete="tel"
                aria-describedby="phone-helper phone-number-error"
                aria-errormessage="phone-number-error"
                placeholder="+1 (555) 123-4567"
              >
              <p id="phone-helper" class="helper-text">Expected format: include country or area code, for example +1 (555) 123-4567.</p>
              <p id="phone-number-error" class="error-text" hidden></p>
            </div>

            <button type="submit">Send request</button>
            <p id="form-status" class="status-message" aria-live="polite"></p>
          </form>
        </div>
      </div>
    </section>
  </main>

  <script>
    const form = document.getElementById("support-form");
    const statusMessage = document.getElementById("form-status");
    const validators = {
      fullName(value) {
        if (!value.trim()) {
          return "Error: Enter your full name.";
        }
        return "";
      },
      email(value) {
        if (!value.trim()) {
          return "Error: Enter your email address.";
        }

        const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
        if (!emailPattern.test(value.trim())) {
          return "Error: Enter a valid email address, like name@example.com.";
        }

        return "";
      },
      phone(value) {
        const trimmedValue = value.trim();
        if (!trimmedValue) {
          return "";
        }

        const phonePattern = /^[+]?[0-9()\s.-]{7,20}$/;
        if (!phonePattern.test(trimmedValue)) {
          return "Error: Enter a phone number in the expected format, like +1 (555) 123-4567.";
        }

        return "";
      }
    };

    function setFieldState(input, message) {
      const errorElement = document.getElementById(input.id + "-error");
      const hasError = Boolean(message);

      input.setAttribute("aria-invalid", String(hasError));
      errorElement.textContent = message;
      errorElement.hidden = !hasError;
    }

    function validateField(input) {
      const validator = validators[input.name];
      const message = validator ? validator(input.value) : "";
      setFieldState(input, message);
      return !message;
    }

    form.addEventListener("submit", function (event) {
      event.preventDefault();

      const inputs = Array.from(form.querySelectorAll("input"));
      const firstInvalidField = inputs.find(function (input) {
        return !validateField(input);
      });

      if (firstInvalidField) {
        statusMessage.textContent = "Please correct the highlighted fields and try again.";
        statusMessage.dataset.state = "error";
        firstInvalidField.focus();
        return;
      }

      statusMessage.textContent = "Your support request is ready to send.";
      statusMessage.dataset.state = "success";
    });

    form.querySelectorAll("input").forEach(function (input) {
      input.addEventListener("blur", function () {
        validateField(input);
      });

      input.addEventListener("input", function () {
        if (input.getAttribute("aria-invalid") === "true") {
          validateField(input);
        }

        if (statusMessage.textContent) {
          statusMessage.textContent = "";
          delete statusMessage.dataset.state;
        }
      });
    });
  </script>
