   <script>
     const form = document.getElementById("support-form");
     const statusMessage = document.getElementById("form-status");
     const validators = {
       fullName(value) {
         if (!value.trim()) {
           return "Error: Enter your full name.";
         }
         return "";
       },
       email(value) {
         if (!value.trim()) {
           return "Error: Enter your email address.";
         }

         const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
         if (!emailPattern.test(value.trim())) {
           return "Error: Enter a valid email address, like name@example.com.";
         }

         return "";
       },
       phone(value) {
         const trimmedValue = value.trim();
         if (!trimmedValue) {
           return "";
         }

         const phonePattern = /^[+]?[0-9()\s.-]{7,20}$/;
         if (!phonePattern.test(trimmedValue)) {
           return "Error: Enter a phone number in the expected format, like +1 (555) 123-4567.";
         }

         return "";
       }
     };

     function setFieldState(input, message) {
       const errorElement = document.getElementById(input.id + "-error");
       const hasError = Boolean(message);

       input.setAttribute("aria-invalid", String(hasError));
       errorElement.textContent = message;
       errorElement.hidden = !hasError;
     }

     function validateField(input) {
       const validator = validators[input.name];
       const message = validator ? validator(input.value) : "";
       setFieldState(input, message);
       return !message;
     }

     form.addEventListener("submit", function (event) {
       event.preventDefault();

       const inputs = Array.from(form.querySelectorAll("input"));
       const firstInvalidField = inputs.find(function (input) {
         return !validateField(input);
       });

       if (firstInvalidField) {
         statusMessage.textContent = "Please correct the highlighted fields and try again.";
         statusMessage.dataset.state = "error";
         firstInvalidField.focus();
         return;
       }

       statusMessage.textContent = "Your support request is ready to send.";
       statusMessage.dataset.state = "success";
     });

     form.querySelectorAll("input").forEach(function (input) {
       input.addEventListener("blur", function () {
         validateField(input);
       });

       input.addEventListener("input", function () {
         if (input.getAttribute("aria-invalid") === "true") {
           validateField(input);
         }

         if (statusMessage.textContent) {
           statusMessage.textContent = "";
           delete statusMessage.dataset.state;
         }
       });
     });
   </script>
