const { chromium } = require('playwright');
(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage({ viewport: { width: 1440, height: 1200 } });
  const pageUrl = 'file://' + path.join(process.env.WORKDIR, 'index.html');
  const results = [];
  async function runAudit(name, setup) {
    await page.goto(pageUrl);
    if (setup) await setup();
    await page.addScriptTag({ path: '/tmp/axe.min.js' });
    const result = await page.evaluate(async () => await window.axe.run());
    results.push({
      state: name,
      wcag: result.violations.filter(v => !v.tags.includes('best-practice')).map(v => ({ id: v.id, impact: v.impact, targets: v.nodes.map(n => n.target) })),
      bestPractice: result.violations.filter(v => v.tags.includes('best-practice')).map(v => ({ id: v.id, impact: v.impact, targets: v.nodes.map(n => n.target) }))
    });
  }
  await runAudit('initial');
  await runAudit('error-state', async () => {
    await page.click('button[type="submit"]');
  });
  await runAudit('success-state', async () => {
    await page.fill('#full-name', 'Jordan Lee');
    await page.fill('#email-address', 'jordan@example.com');
    await page.fill('#phone-number', '+1 (555) 123-4567');
    await page.click('button[type="submit"]');
  });
  await browser.close();
  console.log(JSON.stringify(results, null, 2));
  process.exit(results.some(entry => entry.wcag.length > 0) ? 1 : 0);
})();
